// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2) public {
        vm.assume(blockNum1 != blockNum2);
        vm.assume(blockNum1 % 15 != 0);
        vm.assume(blockNum2 % 15 != 0);

        address sender = address(0x1234);
        vm.deal(sender, 100 ether);

        vm.warp(1000);
        vm.roll(blockNum1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        uint256 pastBeforeSecond = c.pastBlockTime();

        vm.warp(1000);
        vm.roll(blockNum2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2 || c.pastBlockTime() != pastBeforeSecond);
    }
}
